import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { StatusBar } from 'expo-status-bar';

import HomeScreen from './screens/HomeScreen';
import HealthScreen from './screens/HealthScreen';
import TranscribeScreen from './screens/TranscribeScreen';

export type RootStackParamList = {
  Home: undefined;
  Health: undefined;
  Transcribe: undefined;
};

const Stack = createNativeStackNavigator<RootStackParamList>();

export default function App() {
  return (
    <NavigationContainer>
      <Stack.Navigator initialRouteName="Home">
        <Stack.Screen name="Home" component={HomeScreen} options={{ title: 'Native Bench' }} />
        <Stack.Screen name="Health" component={HealthScreen} options={{ title: 'Health' }} />
        <Stack.Screen name="Transcribe" component={TranscribeScreen} options={{ title: 'Transcribe' }} />
      </Stack.Navigator>
      <StatusBar style="auto" />
    </NavigationContainer>
  );
}

