import { useFocusEffect } from '@react-navigation/native';
import { useCallback, useEffect, useState } from 'react';
import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';

import ExpoBenchSpeech from '../modules/expo-bench-speech/src/ExpoBenchSpeechModule';
import { SpeechAuthorizationStatus } from '../modules/expo-bench-speech/src/ExpoBenchSpeech.types';

function statusLineText(status: SpeechAuthorizationStatus): string {
  switch (status) {
    case 'authorized':
      return 'Speech access: granted';
    case 'denied':
      return 'Speech access: denied';
    default:
      return 'Speech access: not requested';
  }
}

function errorText(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export default function TranscribeScreen() {
  const [authStatus, setAuthStatus] = useState<SpeechAuthorizationStatus>('notDetermined');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const [transcript, setTranscript] = useState<string | null>(null);
  const [elapsedSeconds, setElapsedSeconds] = useState<number | null>(null);

  useFocusEffect(
    useCallback(() => {
      setAuthStatus(ExpoBenchSpeech.getAuthorizationStatus());
    }, [])
  );

  useEffect(() => {
    const subscription = ExpoBenchSpeech.addListener('onPartialTranscript', (event) => {
      setTranscript(event.text);
    });
    return () => subscription.remove();
  }, []);

  const handleRequestAccess = async () => {
    setErrorMessage(null);
    try {
      const status = await ExpoBenchSpeech.requestAuthorization();
      setAuthStatus(status);
    } catch (error) {
      setErrorMessage(errorText(error));
    }
  };

  const handleTranscribe = async () => {
    setErrorMessage(null);
    setTranscript(null);
    setElapsedSeconds(null);
    setIsTranscribing(true);
    const startedAt = Date.now();
    try {
      const finalTranscript = await ExpoBenchSpeech.transcribeSample();
      setTranscript(finalTranscript);
      setElapsedSeconds((Date.now() - startedAt) / 1000);
    } catch (error) {
      setErrorMessage(errorText(error));
    } finally {
      setIsTranscribing(false);
    }
  };

  const canTranscribe = authStatus === 'authorized' && !isTranscribing;
  const statusText = isTranscribing ? 'Transcribing…' : errorMessage ?? statusLineText(authStatus);

  return (
    <View style={styles.container}>
      <Text style={styles.status}>{statusText}</Text>

      <Pressable style={styles.button} onPress={handleRequestAccess}>
        <Text style={styles.buttonText}>Request Access</Text>
      </Pressable>
      <Pressable
        style={[styles.button, !canTranscribe && styles.buttonDisabled]}
        disabled={!canTranscribe}
        onPress={handleTranscribe}>
        <Text style={[styles.buttonText, !canTranscribe && styles.buttonTextDisabled]}>Transcribe Sample</Text>
      </Pressable>

      <ScrollView style={styles.transcriptArea} contentContainerStyle={transcript === null && styles.emptyState}>
        {transcript === null ? (
          <Text style={styles.emptyStateText}>No transcript yet</Text>
        ) : (
          <>
            <Text style={styles.transcriptText}>{transcript}</Text>
            {elapsedSeconds !== null && (
              <Text style={styles.completedText}>Completed in {elapsedSeconds.toFixed(1)} s</Text>
            )}
          </>
        )}
      </ScrollView>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#fff',
    padding: 24,
  },
  status: {
    fontSize: 16,
    color: '#333',
    marginBottom: 24,
  },
  button: {
    backgroundColor: '#007AFF',
    borderRadius: 12,
    paddingVertical: 16,
    alignItems: 'center',
    marginBottom: 16,
  },
  buttonDisabled: {
    backgroundColor: '#ccc',
  },
  buttonText: {
    color: '#fff',
    fontSize: 17,
    fontWeight: '600',
  },
  buttonTextDisabled: {
    color: '#888',
  },
  transcriptArea: {
    flex: 1,
    marginTop: 24,
  },
  emptyState: {
    flexGrow: 1,
    alignItems: 'center',
    justifyContent: 'center',
  },
  emptyStateText: {
    fontSize: 16,
    color: '#999',
  },
  transcriptText: {
    fontSize: 16,
    color: '#333',
    lineHeight: 22,
  },
  completedText: {
    fontSize: 14,
    color: '#999',
    marginTop: 12,
  },
});

